import{a as e,i as t,r as n,t as r}from"./app-DUb33vxN.js";var i=JSON.parse(`{"path":"/%E7%AC%AC08%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E6%95%B4%E5%90%88%E7%AE%A1%E7%90%86/8.1%20%E9%A1%B9%E7%9B%AE%E7%AB%A0%E7%A8%8B.html","title":"8.1 项目章程","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第08章 项目整合管理/8.1 项目章程.md"}`),a={name:`8.1 项目章程.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_8-1-项目章程" tabindex="-1"><a class="header-anchor" href="#_8-1-项目章程"><span>8.1 项目章程</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>项目章程是正式批准项目的文件，由项目发起方或高层管理者签署，授权项目经理使用组织资源开展项目工作。</p><h2 id="项目章程的作用" tabindex="-1"><a class="header-anchor" href="#项目章程的作用"><span>项目章程的作用</span></a></h2><h3 id="正式授权" tabindex="-1"><a class="header-anchor" href="#正式授权"><span>正式授权</span></a></h3><ul><li>授权项目经理开展项目</li><li>赋予项目经理使用资源的权力</li></ul><h3 id="明确目标" tabindex="-1"><a class="header-anchor" href="#明确目标"><span>明确目标</span></a></h3><ul><li>明确项目的目的和目标</li><li>为项目提供方向</li></ul><h3 id="建立联系" tabindex="-1"><a class="header-anchor" href="#建立联系"><span>建立联系</span></a></h3><ul><li>建立项目与组织战略的联系</li><li>明确项目的商业价值</li></ul><h3 id="提供依据" tabindex="-1"><a class="header-anchor" href="#提供依据"><span>提供依据</span></a></h3><ul><li>作为项目后续工作的依据</li><li>指导项目规划和执行</li></ul><h2 id="项目章程的内容" tabindex="-1"><a class="header-anchor" href="#项目章程的内容"><span>项目章程的内容</span></a></h2><h3 id="_1-项目基本信息" tabindex="-1"><a class="header-anchor" href="#_1-项目基本信息"><span>1. 项目基本信息</span></a></h3><ul><li>项目名称</li><li>项目编号</li><li>项目发起方</li><li>项目经理</li></ul><h3 id="_2-项目目的和目标" tabindex="-1"><a class="header-anchor" href="#_2-项目目的和目标"><span>2. 项目目的和目标</span></a></h3><ul><li>项目的商业目的</li><li>项目的可交付成果</li><li>项目成功标准</li></ul><h3 id="_3-项目范围描述" tabindex="-1"><a class="header-anchor" href="#_3-项目范围描述"><span>3. 项目范围描述</span></a></h3><ul><li>项目的主要交付物</li><li>项目的边界</li><li>项目的除外责任</li></ul><h3 id="_4-里程碑进度计划" tabindex="-1"><a class="header-anchor" href="#_4-里程碑进度计划"><span>4. 里程碑进度计划</span></a></h3><ul><li>主要里程碑</li><li>里程碑日期</li></ul><h3 id="_5-预算摘要" tabindex="-1"><a class="header-anchor" href="#_5-预算摘要"><span>5. 预算摘要</span></a></h3><ul><li>项目总预算</li><li>资金来源</li></ul><h3 id="_6-项目风险" tabindex="-1"><a class="header-anchor" href="#_6-项目风险"><span>6. 项目风险</span></a></h3><ul><li>主要风险识别</li><li>风险应对策略概述</li></ul><h3 id="_7-项目干系人" tabindex="-1"><a class="header-anchor" href="#_7-项目干系人"><span>7. 项目干系人</span></a></h3><ul><li>关键干系人列表</li><li>干系人职责</li></ul><h3 id="_8-审批信息" tabindex="-1"><a class="header-anchor" href="#_8-审批信息"><span>8. 审批信息</span></a></h3><ul><li>批准人</li><li>批准日期</li><li>授权签字</li></ul><h2 id="项目章程的制定过程" tabindex="-1"><a class="header-anchor" href="#项目章程的制定过程"><span>项目章程的制定过程</span></a></h2><h3 id="_1-收集信息" tabindex="-1"><a class="header-anchor" href="#_1-收集信息"><span>1. 收集信息</span></a></h3><ul><li>收集项目背景信息</li><li>了解组织战略目标</li></ul><h3 id="_2-编写草案" tabindex="-1"><a class="header-anchor" href="#_2-编写草案"><span>2. 编写草案</span></a></h3><ul><li>起草项目章程草案</li><li>征求相关方意见</li></ul><h3 id="_3-评审修改" tabindex="-1"><a class="header-anchor" href="#_3-评审修改"><span>3. 评审修改</span></a></h3><ul><li>组织专家评审</li><li>根据反馈修改</li></ul><h3 id="_4-正式批准" tabindex="-1"><a class="header-anchor" href="#_4-正式批准"><span>4. 正式批准</span></a></h3><ul><li>提交高层审批</li><li>签署项目章程</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>项目章程的作用</strong></li><li><strong>项目章程的内容</strong></li><li><strong>项目章程的制定过程</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>章程批准项目，授权经理开展工作，内容齐全是关键</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：项目章程的主要作用是什么？ A. 详细描述项目计划 B. 正式授权项目经理开展项目 C. 记录项目执行情况 D. 总结项目经验教训</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>：项目章程的主要作用是正式批准项目，授权项目经理使用组织资源开展项目工作。详细描述项目计划是项目管理计划的内容，记录项目执行情况是项目记录的内容，总结项目经验教训是项目收尾的内容。</p>`,46)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};